    16  #define MCINST_CACHE (ARR_SIZE(mcInst->Operands) - 1)
    17
    18  void MCInst_Init(MCInst *inst)
    19  {
    20          unsigned int i;
    21
    22          for (i = 0; i < 48; i++) {
    23                  inst->Operands[i].Kind = kInvalid;
    24          }
    25
    26          inst->Opcode = 0;
    27          inst->OpcodePub = 0;
    28          inst->size = 0;
    29          inst->has_imm = false;
    30          inst->op1_size = 0;
    31          inst->writeback = false;
    32          inst->ac_idx = 0;
    33          inst->popcode_adjust = 0;
    34          inst->assembly[0] = '\0';
    35          inst->wasm_data.type = WASM_OP_INVALID;
    36  }
    37
    38  void MCInst_clear(MCInst *inst)
    39  {
    40          inst->size = 0;
    41  }
    42
    43  // do not free @Op
    44  void MCInst_insert0(MCInst *inst, int index, MCOperand *Op)
    45  {
    46          int i;
    47
    48          for(i = inst->size; i > index; i--)
    49                  //memcpy(&(inst->Operands[i]), &(inst->Operands[i-1]), sizeof(MCOperand));
    50                  inst->Operands[i] = inst->Operands[i-1];
    51
    52          inst->Operands[index] = *Op;
    53          inst->size++;
    54  }
    55
    56  void MCInst_setOpcode(MCInst *inst, unsigned Op)
    57  {
    58          inst->Opcode = Op;
    59  }
    60
    61  void MCInst_setOpcodePub(MCInst *inst, unsigned Op)
    62  {
    63          inst->OpcodePub = Op;
    64  }
    65
    66  unsigned MCInst_getOpcode(const MCInst *inst)
    67  {
    68          return inst->Opcode;
    69  }
    70
    71  unsigned MCInst_getOpcodePub(const MCInst *inst)
    72  {
    73          return inst->OpcodePub;
    74  }
    75
    76  MCOperand *MCInst_getOperand(MCInst *inst, unsigned i)
    77  {
    78          return &inst->Operands[i];
    79  }
    80
    81  unsigned MCInst_getNumOperands(const MCInst *inst)
    82  {
    83          return inst->size;
    84  }
    85
    86  // This addOperand2 function doesnt free Op
    87  void MCInst_addOperand2(MCInst *inst, MCOperand *Op)
    88  {
    89          inst->Operands[inst->size] = *Op;
    90
    91          inst->size++;
    92  }
    93
    94  bool MCOperand_isValid(const MCOperand *op)
    95  {
    96          return op->Kind != kInvalid;
    97  }
    98
    99  bool MCOperand_isReg(const MCOperand *op)
   100  {
   101          return op->Kind == kRegister;
   102  }
   103
   104  bool MCOperand_isImm(const MCOperand *op)
   105  {
   106          return op->Kind == kImmediate;
   107  }
   108
   109  bool MCOperand_isFPImm(const MCOperand *op)
   110  {
   111          return op->Kind == kFPImmediate;
   112  }
   113
   114  /// getReg - Returns the register number.
   115  unsigned MCOperand_getReg(const MCOperand *op)
   116  {
   117          return op->RegVal;
   118  }
   119
   120  /// setReg - Set the register number.
   121  void MCOperand_setReg(MCOperand *op, unsigned Reg)
   122  {
   123          op->RegVal = Reg;
   124  }
   125
   126  int64_t MCOperand_getImm(MCOperand *op)
   127  {
   128          return op->ImmVal;
   129  }
